/* Types */
/**  Whether a repository looks like an Astro site */
export type AstroCheck = "astro" | "notAstro" | 
/**  Empty, unreadable with this sign-in, or GitHub couldn't answer for it */
"unknown";

export type BranchInfo = {
	/**  Short name: `main` for a local branch, `origin/main` for a remote one */
	name: string,
	isRemote: boolean,
	isHead: boolean,
	upstream: string | null,
	ahead: number,
	behind: number,
	/**  Unix seconds of the branch's tip commit */
	lastCommitTime: number,
};

export type ChangedFile = {
	/**  Path relative to the repository root, with forward slashes */
	path: string,
	/**  The previous path, for renames */
	oldPath: string | null,
	change: FileChange,
};

/**  Summary of a pull request's checks (combined status and check runs) */
export type ChecksSummary = "pending" | "success" | "failure" | "none";

/**  Payload of the `git-clone-progress` event */
export type CloneProgress = {
	received: number,
	total: number,
};

export type Collection = {
	name: string,
	path: string,
	/**
	 *  The `base` of the collection's `glob()` loader, relative to the project
	 *  root, when the collection's folder came from it
	 */
	loader_base?: string | null,
	/**
	 *  The folder the collection would be in automatically, when the writer
	 *  set another one that's in use
	 */
	automatic_path?: string | null,
	/**
	 *  The folder the writer set, relative to the project root, when it isn't
	 *  there, so the collection is in its automatic folder instead
	 */
	missing_folder?: string | null,
	/**
	 *  Why the folder the writer set can't be used ("it links outside the
	 *  project"), so the collection is in its automatic folder instead
	 */
	refused_folder?: string | null,
	complete_schema?: string | null,
};

export type CommitDetails = {
	message: string,
	authorEmail: string,
	files: ChangedFile[],
} & GraphCommit;

export type ComponentFramework = "astro" | "react" | "vue" | "svelte";

/**  Which whole-file version to keep for a conflicted file */
export type ConflictChoice = "mine" | "theirs";

/**
 *  A file that conflicts between the current branch and its upstream, with both
 *  whole-file versions for the writer to choose between
 */
export type ConflictFile = {
	/**  Path relative to the repository root, with forward slashes */
	path: string,
	/**  This computer's version; `None` if it was deleted here, or is binary */
	mine: string | null,
	/**  The upstream's version; `None` if it was deleted there, or is binary */
	theirs: string | null,
	binary: boolean,
};

export type ConflictResolution = {
	path: string,
	choice: ConflictChoice,
};

export type DevServerState = {
	status: DevServerStatus,
	url: string | null,
	command: string | null,
	pid: number | null,
	error: string | null,
};

export type DevServerStatus = "stopped" | 
/**  Installing dependencies before starting */
"installing" | "starting" | "running" | 
/**  Another server for the project was already running, started elsewhere */
"external" | "error";

export type DeviceCode = {
	userCode: string,
	verificationUri: string,
	/**  Seconds until the code expires */
	expiresIn: number,
	/**  Seconds to wait between polls */
	interval: number,
};

export type DiffHunk = {
	header: string,
	lines: DiffLine[],
};

export type DiffLine = {
	kind: DiffLineKind,
	/**  The line without its trailing newline */
	text: string,
	oldNo: number | null,
	newNo: number | null,
};

export type DiffLineKind = "add" | "del" | "ctx";

export type DirectoryInfo = {
	name: string,
	relative_path: string,
	full_path: string,
};

export type DirectoryScanResult = {
	subdirectories: DirectoryInfo[],
	files: FileEntry[],
};

/**
 *  A collection entry picked for an entry prop, which the file loads with
 *  `getEntry`
 */
export type EntryImport = {
	/**  The prop it was picked for */
	prop: string,
	collection: string,
	/**  The entry's id in Astro */
	id: string,
};

/**  How a file differs from `HEAD`. */
export type FileChange = "added" | "modified" | "deleted" | "renamed" | "untracked" | "conflicted";

export type FileDiff = {
	path: string,
	binary: boolean,
	isImage: boolean,
	hunks: DiffHunk[],
};

export type FileEntry = {
	id: string,
	path: string,
	name: string,
	extension: string,
	collection: string,
	last_modified: number | null,
	frontmatter: { [key in string]: Value } | null,
};

/**  Whether a registered project's folder is there */
export type FolderState = 
/**  The folder is there */
"present" | 
/**  The folder is gone from a place that's there: moved or deleted */
"missing" | 
/**
 *  It can't be told: its drive isn't connected (the parent is gone too),
 *  it can't be read, or something other than a folder is there now
 */
"unavailable";

export type GitHubAuthStatus = {
	signedIn: boolean,
	login: string | null,
	name: string | null,
	avatarUrl: string | null,
};

export type GitStatus = {
	isRepo: boolean,
	branch: string | null,
	defaultBranch: string | null,
	/**  The upstream branch's short name, e.g. `origin/main` */
	upstream: string | null,
	ahead: number,
	behind: number,
	files: ChangedFile[],
	detached: boolean,
};

/**  The English dialects Harper supports */
export type GrammarDialect = "american" | "british" | "canadian" | "australian" | "indian";

/**
 *  Which parser rules apply. MDX adds masking for imports, component tags and
 *  `{expressions}`, which Harper's Markdown parser doesn't know about
 */
export type GrammarFileType = "md" | "mdx";

/**  One problem Harper found */
export type GrammarIssue = {
	/**  Start, in UTF-16 code units from the start of the text */
	from: number,
	/**  End (exclusive), in UTF-16 code units */
	to: number,
	/**  Harper's rule name, such as `SpellCheck` */
	rule: string,
	kind: GrammarIssueKind,
	/**  The text between `from` and `to` */
	problem: string,
	message: string,
	/**  Replacement text for `from..to`, best first. An empty string removes it */
	suggestions: string[],
};

/**  Spelling issues get their own underline; everything else is grammar */
export type GrammarIssueKind = "spelling" | "grammar";

export type GraphCommit = {
	id: string,
	shortId: string,
	parents: string[],
	summary: string,
	authorName: string,
	/**  Unix seconds */
	time: number,
	refs: GraphRef[],
};

export type GraphRef = {
	name: string,
	kind: RefKind,
};

/**  An image picked for an image prop, which the file has to import */
export type ImageImport = {
	/**  The prop it was picked for */
	prop: string,
	/**  The picked file's name, which the import's binding is named after */
	file_name: string,
	/**  The path to import it from, as the editor writes image paths */
	specifier: string,
};

export type ImportPlan = {
	/**  The import block with everything added */
	imports: string,
	/**  The statements added or changed, in the order they're in the block */
	added: string[],
	/**
	 *  The statement that already has the component's name, if one does. It may
	 *  be something else of the same name, and then the writer's import wins.
	 */
	existing: string | null,
	/**
	 *  The name each picked image or entry is imported or loaded as, by the
	 *  prop it was picked for
	 */
	names: { [key in string]: string },
};

export type MarkdownContent = {
	frontmatter: { [key in string]: Value },
	content: string,
	raw_frontmatter: string,
	imports: string,
};

export type MdxComponent = {
	name: string,
	/**  Relative path from project root; empty for components from a package */
	file_path: string,
	props: PropInfo[],
	has_slot: boolean,
	description: string | null,
	framework: ComponentFramework,
	/**
	 *  The module a package's components are imported from, e.g. `@astrojs/starlight/components`;
	 *  `None` for the project's own components
	 */
	import_source: string | null,
	/**  Imported by name (`import { Aside } from …`) rather than as its module's default export */
	named_export: boolean,
	/**
	 *  Content inserted inside the tag instead of an empty slot, as a CodeMirror snippet,
	 *  e.g. the `TabItem`s inside `Tabs`
	 */
	slot_template: string | null,
};

export type PreviewKind = 
/**  A screenshot of the site's home page */
"screenshot" | 
/**  The site's share image from `public/` */
"share-image";

/**  A site's preview image */
export type ProjectPreview = {
	kind: PreviewKind,
	/**  A `data:` URL of a JPEG, at most 800 px wide */
	src: string,
	/**  When the screenshot was taken (ISO 8601); null for a share image */
	takenAt: string | null,
};

/**  Payload of the `project-preview-updated` event */
export type ProjectPreviewUpdated = {
	projectPath: string,
};

/**  What was picked for the props whose values the file has to import or load */
export type PropImports = {
	images: ImageImport[],
	entries: EntryImport[],
};

export type PropInfo = {
	name: string,
	prop_type: string,
	kind: PropKind,
	is_optional: boolean,
	/**  The default from destructuring, as source: strings unquoted, anything else verbatim */
	default_value: string | null,
	description: string | null,
};

/**
 *  What kind of value a prop takes, resolved from its TypeScript type.
 *  The component builder picks a control for each kind; `Unknown` gets a text field.
 */
export type PropKind = { kind: "string" } | { kind: "number" } | { kind: "boolean" } | 
/**  A union of string literals, e.g. `'sm' | 'md' | 'lg'`, or a string enum */
{ kind: "literals"; values: string[] } | { kind: "array"; items: PropKind } | { kind: "date" } | 
/**  Astro's `ImageMetadata` */
{ kind: "image" } | 
/**  `CollectionEntry<'blog'>` from `astro:content` */
{ kind: "collectionEntry"; collection: string } | { kind: "unknown" };

export type PublishResult = {
	commitId: string,
	pushed: boolean,
	outcome: SyncOutcome,
	message: string,
	status: GitStatus,
};

export type PullRequest = {
	number: number,
	title: string,
	head: string,
	base: string,
	state: PullRequestState,
	draft: boolean,
	htmlUrl: string,
	mergeable: boolean | null,
	checks: ChecksSummary,
};

export type PullRequestState = "open" | "closed" | "merged";

export type RefKind = "head" | "localBranch" | "remoteBranch" | "tag";

/**  One repository's answer */
export type RepoAstroCheck = {
	fullName: string,
	check: AstroCheck,
};

export type RepoInfo = {
	owner: string,
	repo: string,
	defaultBranch: string,
	htmlUrl: string,
};

/**  A repository the signed-in user can clone */
export type RepoSummary = {
	fullName: string,
	owner: string,
	name: string,
	private: boolean,
	defaultBranch: string,
	cloneUrl: string,
	/**  ISO 8601, as GitHub returns it */
	updatedAt: string,
	/**
	 *  ISO 8601: when the last commit was pushed. Changes only with a push, which
	 *  is what the "is it an Astro site" cache is keyed on.
	 */
	pushedAt: string | null,
};

export type SyncOutcome = "upToDate" | "fastForwarded" | "merged" | "blockedByLocalChanges" | "conflict" | "noUpstream";

export type SyncResult = {
	outcome: SyncOutcome,
	/**  A plain-language sentence for the writer */
	message: string,
	status: GitStatus,
};

/**
 *  A `.json` file in the themes folder. `problem` is set when the file must not
 *  be read, and says why in plain words.
 */
export type ThemeFileEntry = {
	name: string,
	problem: string | null,
};

export type Value = null | boolean | number | string | Value[] | { [key in string]: Value };

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

